class SinglyLinkedList:
    """Singly linked list implementation."""
    def __init__(self) -> None:
        self.head: Any = None
        self._size: int = 0

    def append(self, val: Any) -> None:
        new_node = Node(val)
        if not self.head:
            self.head = new_node
        else:
            curr = self.head
            while curr.next:
                curr = curr.next
            curr.next = new_node
        self._size += 1

    def prepend(self, val: Any) -> None:
        self.head = Node(val, self.head)
        self._size += 1

    def delete(self, val: Any) -> bool:
        curr = self.head
        prev = None
        while curr:
            if curr.val == val:
                if prev:
                    prev.next = curr.next
                else:
                    self.head = curr.next
                self._size -= 1
                return True
            prev = curr
            curr = curr.next
        return False

    def find(self, val: Any) -> bool:
        curr = self.head
        while curr:
            if curr.val == val:
                return True
            curr = curr.next
        return False

    def to_list(self) -> list:
        res = []
        curr = self.head
        while curr:
            res.append(curr.val)
            curr = curr.next
        return res

    def __len__(self) -> int:
        return self._size

