class DoublyLinkedList:
    """Doubly linked list with bidirectional traversal."""
    def __init__(self) -> None:
        self.head: Any = None
        self.tail: Any = None
        self.size: int = 0

    def insert_front(self, val: Any) -> None:
        node = DoublyNode(val, next=self.head)
        if self.head:
            self.head.prev = node
        else:
            self.tail = node
        self.head = node
        self.size += 1

    def insert_back(self, val: Any) -> None:
        node = DoublyNode(val, prev=self.tail)
        if self.tail:
            self.tail.next = node
        else:
            self.head = node
        self.tail = node
        self.size += 1

    def remove_node(self, node: DoublyNode) -> None:
        if node.prev:
            node.prev.next = node.next
        else:
            self.head = node.next
        if node.next:
            node.next.prev = node.prev
        else:
            self.tail = node.prev
        self.size -= 1

    def traverse_backward(self) -> list:
        res = []
        curr = self.tail
        while curr:
            res.append(curr.val)
            curr = curr.prev
        return res

