class BinarySearchTree:
    """Binary Search Tree implementation."""
    def __init__(self) -> None:
        self.root: Any = None

    def insert(self, val: int) -> None:
        if not self.root:
            self.root = BSTNode(val)
        else:
            self._insert(self.root, val)

    def _insert(self, node: BSTNode, val: int) -> None:
        if val < node.val:
            if node.left:
                self._insert(node.left, val)
            else:
                node.left = BSTNode(val)
        elif val > node.val:
            if node.right:
                self._insert(node.right, val)
            else:
                node.right = BSTNode(val)

    def search(self, val: int) -> bool:
        curr = self.root
        while curr:
            if val == curr.val:
                return True
            curr = curr.left if val < curr.val else curr.right
        return False

    def inorder_traversal(self) -> list[int]:
        res: list[int] = []
        def _inorder(node: Any) -> None:
            if node:
                _inorder(node.left)
                res.append(node.val)
                _inorder(node.right)
        _inorder(self.root)
        return res

    def delete(self, val: int) -> None:
        self.root = self._delete_node(self.root, val)

    def _delete_node(self, root: Any, val: int) -> Any:
        if not root:
            return None
        if val < root.val:
            root.left = self._delete_node(root.left, val)
        elif val > root.val:
            root.right = self._delete_node(root.right, val)
        else:
            if not root.left:
                return root.right
            if not root.right:
                return root.left
            succ = root.right
            while succ.left:
                succ = succ.left
            root.val = succ.val
            root.right = self._delete_node(root.right, succ.val)
        return root

