class Deque:
    """Double-ended queue implementation."""
    def __init__(self) -> None:
        self.head: Any = None
        self.tail: Any = None
        self._len: int = 0

    def push_front(self, val: Any) -> None:
        node = DequeNode(val)
        if not self.head:
            self.head = self.tail = node
        else:
            node.next = self.head
            self.head.prev = node
            self.head = node
        self._len += 1

    def push_back(self, val: Any) -> None:
        node = DequeNode(val)
        if not self.tail:
            self.head = self.tail = node
        else:
            self.tail.next = node
            node.prev = self.tail
            self.tail = node
        self._len += 1

    def pop_front(self) -> Any:
        if not self.head:
            raise IndexError("pop from empty deque")
        val = self.head.val
        self.head = self.head.next
        if self.head:
            self.head.prev = None
        else:
            self.tail = None
        self._len -= 1
        return val

    def pop_back(self) -> Any:
        if not self.tail:
            raise IndexError("pop from empty deque")
        val = self.tail.val
        self.tail = self.tail.prev
        if self.tail:
            self.tail.next = None
        else:
            self.head = None
        self._len -= 1
        return val

    def is_empty(self) -> bool:
        return self._len == 0

    def __len__(self) -> int:
        return self._len

