class SuffixArray:
    """Suffix array builder and pattern searcher."""
    def __init__(self, text: str) -> None:
        self.text: str = text
        self.sa: list[int] = sorted(range(len(text)), key=lambda i: text[i:])

    def search(self, pattern: str) -> bool:
        if not pattern:
            return True
        low, high = 0, len(self.sa) - 1
        while low <= high:
            mid = (low + high) // 2
            suffix = self.text[self.sa[mid]:]
            if suffix.startswith(pattern):
                return True
            elif suffix < pattern:
                low = mid + 1
            else:
                high = mid - 1
        return False

    def count_occurrences(self, pattern: str) -> int:
        if not pattern:
            return 0
        n = len(self.sa)
        # Find lower bound
        low, high = 0, n
        while low < high:
            mid = (low + high) // 2
            if self.text[self.sa[mid]:] >= pattern:
                high = mid
            else:
                low = mid + 1
        start = low

        # Find upper bound
        high = n
        while low < high:
            mid = (low + high) // 2
            if self.text[self.sa[mid]:].startswith(pattern):
                low = mid + 1
            elif self.text[self.sa[mid]:] < pattern:
                low = mid + 1
            else:
                high = mid
        return high - start

