def counting_sort(arr: list[int]) -> list[int]:
    """Counting sort for non-negative integer arrays."""
    if not arr:
        return []
    max_val = max(arr)
    min_val = min(arr)
    if min_val < 0:
        raise ValueError("Counting sort expects non-negative integers")
    count = [0] * (max_val + 1)
    for num in arr:
        count[num] += 1
    output = []
    for num, freq in enumerate(count):
        output.extend([num] * freq)
    return output

