def bucket_sort(arr: list[float]) -> list[float]:
    """Bucket sort for floats uniformly distributed in [0, 1)."""
    if not arr:
        return []
    n = len(arr)
    buckets: list[list[float]] = [[] for _ in range(n)]
    for x in arr:
        idx = min(int(n * x), n - 1)
        buckets[idx].append(x)
    for b in buckets:
        b.sort()
    return [x for b in buckets for x in b]

