def binary_search_bounds(arr: list[int], target: int) -> tuple[int, int]:
    """Find first and last occurrence indices of target in sorted array."""
    if not arr:
        return -1, -1

    # Find lower bound
    low, high = 0, len(arr) - 1
    first = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] >= target:
            if arr[mid] == target:
                first = mid
            high = mid - 1
        else:
            low = mid + 1

    # Find upper bound
    low, high = 0, len(arr) - 1
    last = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] <= target:
            if arr[mid] == target:
                last = mid
            low = mid + 1
        else:
            high = mid - 1

    return first, last

