import bisect

def longest_increasing_subsequence_patience(nums: list[int]) -> int:
    """O(N log N) Longest Increasing Subsequence length."""
    tails: list[int] = []
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

