            body_idx = i + 1
            break
        if ":" in line:
            k, v = line.split(":", 1)
            headers[k.strip().lower()] = v.strip()

    body = "\n".join(lines[body_idx:]) if body_idx < len(lines) else ""
    return {
        "method": method,
        "path": path,
        "version": version,
        "headers": headers,
        "body": body,
