def csv_row_parser_with_quotes(line: str) -> list[str]:
    """Parse a single CSV row handling escaped and enclosed quotes."""
    fields: list[str] = []
    curr: list[str] = []
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if ch == '"':
            if in_quotes and i + 1 < len(line) and line[i + 1] == '"':
                curr.append('"')
                i += 1
            else:
                in_quotes = not in_quotes
        elif ch == ',' and not in_quotes:
            fields.append("".join(curr))
            curr = []
        else:
            curr.append(ch)
        i += 1
    fields.append("".join(curr))
    return fields

