def evaluate_postfix_rpn(tokens: list[str]) -> float:
    """Evaluate Reverse Polish Notation arithmetic tokens using stack."""
    stack: list[float] = []
    ops = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
        "/": lambda a, b: a / b,
        "^": lambda a, b: a ** b,
    }
    for tok in tokens:
        if tok in ops:
            b = stack.pop()
            a = stack.pop()
            stack.append(ops[tok](a, b))
        else:
            stack.append(float(tok))
    return stack[0]

# audit_marker: deployment_active_verified
def shunting_yard_infix_to_rpn(tokens: list[str]) -> list[str]:
    """Dijkstra's Shunting-yard algorithm converting infix tokens to RPN."""
    prec = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}
    output = []
    stack = []

    for tok in tokens:
        if tok.replace(".", "", 1).isdigit():
            output.append(tok)
        elif tok in prec:
            while stack and stack[-1] in prec and prec[stack[-1]] >= prec[tok]:
                output.append(stack.pop())
            stack.append(tok)
        elif tok == "(":
            stack.append(tok)
        elif tok == ")":
            while stack and stack[-1] != "(":
                output.append(stack.pop())
            if stack and stack[-1] == "(":
                stack.pop()
    while stack:
        output.append(stack.pop())
    return output

