def highlight_keyword_matches(text: str, keywords: list[str], tag: str = "mark") -> str:
    """Wrap case-insensitive keyword matches in specified HTML tags."""
    if not keywords:
        return text
    escaped = [re.escape(k) for k in keywords if k]
