def count_ngram_frequencies(text: str, n: int = 2) -> dict[str, int]:
    """Compute word n-gram frequencies from text string."""
    words = text.strip().split()
    if len(words) < n or n <= 0:
        return {}
    freqs: dict[str, int] = {}
    for i in range(len(words) - n + 1):
