def stemmer_porter_suffix_rules(word: str) -> str:
    """Apply basic rule-based suffix reduction to English word."""
    w = word.lower()
    suffixes = [("sses", "ss"), ("ies", "i"), ("ss", "ss"), ("s", "")]
    for suf, repl in suffixes:
