def detect_balanced_delimiters(s: str) -> bool:
    """Verify balanced nesting of multiple delimiter pairs: (), [], {}, <>."""
    stack: list[str] = []
    pairs = {")": "(", "]": "[", "}": "{", ">": "<"}
    opening = set(pairs.values())

    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return len(stack) == 0

