def generate_prime_factors_count(n: int) -> dict[int, int]:
    """Return prime factorization mapping prime factors to their exponent powers."""
    if n <= 1:
        return {}
    factors: dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
